/**
 * Minimal bootbox-compatible API for Bootstrap 5.
 *
 * Provides bootbox.alert, bootbox.confirm, bootbox.prompt and bootbox.dialog
 * built on top of Bootstrap 5's bootstrap.Modal. Drop-in replacement for the
 * subset of bootbox 4.x used by orchestrator: jQuery-flavoured API, dialogs
 * created on the fly, callbacks fired on confirm/cancel.
 */
(function (root, factory) {
    if (typeof define === "function" && define.amd) {
        define(["jquery"], factory);
    } else if (typeof exports === "object") {
        module.exports = factory(require("jquery"));
    } else {
        root.bootbox = factory(root.jQuery);
    }
}(this, function ($) {
    "use strict";

    function ensureContainer() {
        var c = document.getElementById("bootbox-container");
        if (!c) {
            c = document.createElement("div");
            c.id = "bootbox-container";
            document.body.appendChild(c);
        }
        return c;
    }

    function buildModal(opts) {
        var modal = document.createElement("div");
        modal.className = "modal fade bootbox";
        modal.tabIndex = -1;
        modal.setAttribute("role", "dialog");

        var dialog = document.createElement("div");
        dialog.className = "modal-dialog";
        modal.appendChild(dialog);

        var content = document.createElement("div");
        content.className = "modal-content";
        dialog.appendChild(content);

        if (opts.title) {
            var header = document.createElement("div");
            header.className = "modal-header";
            var title = document.createElement("h5");
            title.className = "modal-title";
            title.innerHTML = opts.title;
            header.appendChild(title);
            if (opts.closeButton !== false) {
                var close = document.createElement("button");
                close.type = "button";
                close.className = "btn-close";
                close.setAttribute("aria-label", "Close");
                close.setAttribute("data-bs-dismiss", "modal");
                header.appendChild(close);
            }
            content.appendChild(header);
        }

        var body = document.createElement("div");
        body.className = "modal-body";
        var bodyInner = document.createElement("div");
        bodyInner.className = "bootbox-body";
        if (opts.message instanceof HTMLElement) {
            bodyInner.appendChild(opts.message);
        } else if (opts.message && opts.message.jquery) {
            bodyInner.appendChild(opts.message[0]);
        } else {
            bodyInner.innerHTML = opts.message == null ? "" : opts.message;
        }
        body.appendChild(bodyInner);
        content.appendChild(body);

        var footer = null;
        if (opts.buttons && Object.keys(opts.buttons).length > 0) {
            footer = document.createElement("div");
            footer.className = "modal-footer";
            content.appendChild(footer);
        }

        ensureContainer().appendChild(modal);
        return { modal: modal, body: bodyInner, footer: footer };
    }

    function makeButton(key, def, ctx) {
        var btn = document.createElement("button");
        btn.type = "button";
        var cls = def.className;
        if (!cls) {
            if (key === "confirm" || key === "ok") cls = "btn-primary";
            else cls = "btn-secondary";
        }
        btn.className = "btn " + cls;
        btn.setAttribute("data-bb-handler", key);
        btn.textContent = def.label || key;
        btn.addEventListener("click", function () {
            var result = true;
            if (typeof def.callback === "function") {
                result = def.callback.call(ctx.modalInstance, ctx.userValue);
            }
            if (result !== false) {
                ctx.bsModal.hide();
            }
        });
        return btn;
    }

    function showModal(opts) {
        var parts = buildModal(opts);
        var bsModal = new bootstrap.Modal(parts.modal, {
            backdrop: opts.backdrop !== false ? (opts.backdrop === "static" ? "static" : true) : false,
            keyboard: opts.keyboard !== false,
            focus: true
        });
        var ctx = { bsModal: bsModal, modalInstance: parts.modal, userValue: undefined };

        if (parts.footer && opts.buttons) {
            Object.keys(opts.buttons).forEach(function (key) {
                parts.footer.appendChild(makeButton(key, opts.buttons[key], ctx));
            });
        }

        if (typeof opts.onShown === "function") {
            parts.modal.addEventListener("shown.bs.modal", opts.onShown);
        }
        parts.modal.addEventListener("hidden.bs.modal", function () {
            parts.modal.remove();
        });
        // Pressing Escape closes via Bootstrap's keyboard handling; we just
        // need to make sure onEscape fires too.
        if (typeof opts.onEscape === "function") {
            parts.modal.addEventListener("hide.bs.modal", function escapeHandler(e) {
                // Only invoke if dismissal source is keyboard/backdrop, not a
                // button click (buttons already handle their own callback).
                if (parts.modal._bbHandled) return;
                parts.modal._bbHandled = true;
                opts.onEscape();
            });
        }
        bsModal.show();
        return $(parts.modal);
    }

    function normalizeArgs(args, names) {
        if (args.length === 1 && typeof args[0] === "object") {
            return args[0];
        }
        var opts = {};
        for (var i = 0; i < args.length && i < names.length; i++) {
            opts[names[i]] = args[i];
        }
        return opts;
    }

    var bootbox = {};

    bootbox.dialog = function (opts) {
        return showModal(opts);
    };

    bootbox.alert = function () {
        var opts = normalizeArgs(arguments, ["message", "callback"]);
        var dispatched = false;
        var dispatch = function () {
            if (dispatched) return true;
            dispatched = true;
            if (typeof opts.callback === "function") opts.callback();
            return true;
        };
        return showModal({
            title: opts.title,
            message: opts.message,
            buttons: {
                ok: { label: "OK", className: "btn-primary", callback: dispatch }
            },
            onEscape: dispatch
        });
    };

    bootbox.confirm = function () {
        var opts = normalizeArgs(arguments, ["message", "callback"]);
        if (typeof opts.callback !== "function") {
            throw new Error("bootbox.confirm requires a callback");
        }
        var dispatched = false;
        var dispatch = function (value) {
            if (dispatched) return true;
            dispatched = true;
            opts.callback(value);
            return true;
        };
        return showModal({
            title: opts.title,
            message: opts.message,
            buttons: {
                cancel: { label: "Cancel", className: "btn-secondary", callback: function () { return dispatch(false); } },
                confirm: { label: "OK", className: "btn-primary", callback: function () { return dispatch(true); } }
            },
            onEscape: function () { dispatch(false); }
        });
    };

    bootbox.prompt = function () {
        var opts = normalizeArgs(arguments, ["title", "callback"]);
        if (typeof opts.callback !== "function") {
            throw new Error("bootbox.prompt requires a callback");
        }
        var input = document.createElement("input");
        input.type = opts.inputType || "text";
        input.className = "form-control bootbox-input";
        input.autocomplete = "off";
        if (opts.value != null) input.value = opts.value;
        if (opts.placeholder) input.placeholder = opts.placeholder;
        if (opts.pattern) input.pattern = opts.pattern;

        var form = document.createElement("form");
        form.className = "bootbox-form";
        form.appendChild(input);

        var dispatched = false;
        var dispatch = function (value) {
            if (dispatched) return true;
            dispatched = true;
            opts.callback(value);
            return true;
        };

        form.addEventListener("submit", function (e) {
            e.preventDefault();
            dispatch(input.value);
            $(modalEl).modal && bootstrap.Modal.getInstance(modalEl).hide();
        });

        var modalRef = showModal({
            title: opts.title || "Prompt",
            message: form,
            buttons: {
                cancel: { label: "Cancel", className: "btn-secondary", callback: function () { return dispatch(null); } },
                confirm: { label: "OK", className: "btn-primary", callback: function () { return dispatch(input.value); } }
            },
            onShown: function () { input.focus(); },
            onEscape: function () { dispatch(null); }
        });
        var modalEl = modalRef[0];
        return modalRef;
    };

    bootbox.hideAll = function () {
        document.querySelectorAll(".modal.bootbox").forEach(function (m) {
            var inst = bootstrap.Modal.getInstance(m);
            if (inst) inst.hide();
        });
    };

    return bootbox;
}));
